+      if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
+      e.preventDefault();
+      const idx = tabs.indexOf(t);
+      const next = e.key === 'ArrowRight' ? idx + 1 : idx - 1;
+      const el = tabs[(next + tabs.length) % tabs.length];
+      el.focus();
+      activate(el.getAttribute('aria-controls'));
+    });
