from html.parser import HTMLParser
from pathlib import Path

class P(HTMLParser):
  def __init__(self):
    super().__init__()
    self.scripts=[]
    self.titles=[]
    self._intitle=False
  def handle_starttag(self, tag, attrs):
    if tag=='script':
      d=dict(attrs)
      if 'src' in d:
        self.scripts.append(d['src'])
    if tag=='title':
      self._intitle=True
  def handle_endtag(self, tag):
    if tag=='title':
      self._intitle=False
  def handle_data(self, data):
    if self._intitle:
      self.titles.append(data.strip())

files=['index.html','online-courses.html','digital-downloads.html','memberships.html','coaching.html']
for f in files:
  p=P()
  html=Path('/app/output',f).read_text(encoding='utf-8')
  p.feed(html)
  title=''.join(p.titles)
  has_shared=any('assets/shared.js' in s for s in p.scripts)
  has_script=any('assets/script.js' in s for s in p.scripts)
  print(f, 'title:', title, 'shared:', has_shared, 'script:', has_script)
PY

